get.description:
Each sample's probability distribution, for API consumers that want only
the plot data. The Results page renders from GET /api/analysis/{id}
instead.

outputs.response_text:
/*
  Site / model
  Exported from RadiCal (7184f948e7ef) on 2026-10-23.
  Not written, because OxCal's language here cannot say it:
    - Sequence Site: TPQ 900 cal BP, TAQ 400 cal BP
*/
Options()
{
  Resolution=10;
};
Plot()
{
  Curve("SHCal20","shcal20.14c");
  Sequence("Site")
  {
    Boundary("Start");
    Phase("Layer")
    {
      Curve("SHCal20");
      R_Date("LA0",614,25);
      R_Date("LA1",640,25);
      R_Date("LA2",655,25);
    };
    Boundary("End");
  };
};

